import { cache } from 'react';
import { unstable_cache } from 'next/cache';
import { getAllProducts } from './db.js';

/**
 * Cached product fetcher with "products" cache tag.
 * This function is read-optimized and avoids re-querying on every request.
 */
export const getCachedProducts = unstable_cache(
  async () => {
    return await getAllProducts();
  },
  ['products-data'],
  {
    tags: ['products'],
    revalidate: false // Only revalidate on explicit tag invalidation
  }
);

