import { revalidateTag } from 'next/cache';
import { getCachedProducts } from '@/lib/products';

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';

    // Trigger background revalidation
    revalidateTag('products');

    // Return immediately without blocking
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1 style={{ margin: 0 }}>Product Catalog Admin</h1>

        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '0.875rem',
              fontWeight: '500'
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div style={{
        backgroundColor: '#f5f5f5',
        padding: '1rem',
        borderRadius: '4px',
        marginBottom: '1rem',
        fontSize: '0.875rem',
        color: '#666'
      }}>
        Catalog data is cached for fast browsing. Click "Sync latest catalog" to refresh from ERP/PIM in the background.
      </div>

      <div style={{
        border: '1px solid #e0e0e0',
        borderRadius: '8px',
        overflow: 'hidden'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#fafafa', borderBottom: '1px solid #e0e0e0' }}>
              <th style={{ padding: '1rem', textAlign: 'left', fontWeight: '600' }}>ID</th>
              <th style={{ padding: '1rem', textAlign: 'left', fontWeight: '600' }}>Product Name</th>
              <th style={{ padding: '1rem', textAlign: 'right', fontWeight: '600' }}>Price</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product, index) => (
              <tr
                key={product.id}
                style={{
                  borderBottom: index < products.length - 1 ? '1px solid #e0e0e0' : 'none',
                  backgroundColor: 'white'
                }}
              >
                <td style={{ padding: '1rem' }}>{product.id}</td>
                <td style={{ padding: '1rem' }}>{product.name}</td>
                <td style={{ padding: '1rem', textAlign: 'right' }}>${product.price}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div style={{
        marginTop: '1rem',
        fontSize: '0.875rem',
        color: '#666'
      }}>
        Showing {products.length} products
      </div>
    </div>
  );
}

